namespace LSE.AutoCADElectrical.WireToFrom;
public static class DiagnosticsService {
 public static string BuildReport(){var x=new List<string>{"LSE_ToFrom diagnostics  "+DateTime.Now.ToString("s"),"Assembly: "+typeof(DiagnosticsService).Assembly.Location,"Version: "+(typeof(DiagnosticsService).Assembly.GetName().Version?.ToString()??"?")+"  runtime "+Environment.Version+"  user "+Environment.UserName,""};
  AppSettings s;try{s=SettingsService.Load();x.Add("Settings: "+SettingsService.SettingsPath+(File.Exists(SettingsService.SettingsPath)?"":"  (not written yet; defaults in use)"));}catch(Exception ex){x.Add("Settings: FAIL "+ex.Message);return string.Join(Environment.NewLine,x);}
  x.Add("  Config JSON: "+s.ConfigPath+(File.Exists(s.ConfigPath)?"":"  MISSING (built-in defaults in use)"));x.Add("  Data source: "+s.DataSource+"  |  stale policy: "+s.StalePolicy+"  |  backups: "+s.BackupFolderName+" keep "+s.BackupsToKeep+"  |  current drawing only: "+s.CurrentDrawingOnly);
  x.Add("  Active project LISP: "+s.ActiveProjectLisp);x.Add("  Scratch db LISP: "+s.ScratchDbLisp);x.Add("  Refresh LISP: "+(s.RefreshDbLisp.Length>0?s.RefreshDbLisp:"(none; refresh the database by running a native report before LSETOFROM)"));x.Add("  Logs: "+SettingsService.LogFolder);x.Add("");
  ToFromConfig c;try{c=ConfigService.Load(s.ConfigPath);x.Add("Config: "+c.Source);}catch(Exception ex){x.Add("Config: FAIL "+ex.Message);return string.Join(Environment.NewLine,x);}
  x.Add("  Identifier: format "+c.Format+"  far end "+c.FarEndFormat+"  tag:pin "+c.TagPinFormat+"  missing pin '"+c.MissingPinText+"'  missing tag '"+c.MissingTagText+"'  location "+(c.IncludeLocation?c.LocationFormat:"omitted")+"  upper "+c.Uppercase+"  max "+(c.MaxLength>0?c.MaxLength.ToString():"none")+(c.SwapEnds?"  ENDS SWAPPED":""));
  var sc=c.Schematic;x.Add("  Schematic: label at "+sc.LabelAt+" end  layer "+sc.LabelLayer+"  blocks "+sc.BlockH+" / "+sc.BlockV+"  attributes "+sc.TextAttribute+", "+sc.NodeAttribute+(sc.ShowNode?" (shown)":" (hidden)")+", "+sc.KeyAttribute+"  height "+sc.TextHeight+"  offsets end "+sc.EndOffset+" side "+sc.SideOffset+"  collision "+sc.CollisionDistance+"/"+sc.CollisionStep+" x"+sc.CollisionTries+"  reposition "+sc.RepositionOnRerun+"  delete stale "+sc.DeleteStale);
  x.Add("  Block DWGs: "+string.Join("; ",RunService.LibraryPaths(c).Select(f=>f+(File.Exists(Path.Combine(f,sc.BlockH+".dwg"))&&File.Exists(Path.Combine(f,sc.BlockV+".dwg"))?" (both present)":" (not present; definitions are created in the drawing, or run LSETOFROMBLOCKS)"))));
  x.Add("  CSV: delimiter '"+(c.Csv.Delimiter=="\t"?"tab":c.Csv.Delimiter)+"'  encoding "+c.Csv.Encoding+"  reverse at far end "+c.Csv.ReverseAtFarEnd+"  output "+c.Csv.OutputFolder+"\\"+c.Csv.LabelFile+", "+c.Csv.ReportFile+", "+c.Csv.ValidationFile);
  x.Add("  Database: path "+c.Database.PathPattern+"  providers "+string.Join(",",c.Database.Providers)+"  index base "+c.Database.DrawingIndexBase+"  confidence "+c.Database.Confidence);x.Add("    wireSql: "+(c.Database.WireSql.Length>0?c.Database.WireSql:"(EMPTY: run LSETOFROMDISCOVER on a project)"));x.Add("    drawingSql: "+(c.Database.DrawingSql.Length>0?c.Database.DrawingSql:"(none; drawing index = position in the .wdp list)"));
  x.Add("    columns: "+string.Join(", ",c.Database.Columns.All().Select(k=>k.Role+"="+(k.Column.Length>0?k.Column:"-")+(k.Required?"*":""))));x.Add("");
  x.Add("ADODB: "+(Type.GetTypeFromProgID("ADODB.Connection") is not null?"available":"NOT AVAILABLE (the project database cannot be read)"));
  foreach(string p in c.Database.Providers){string state;try{Type t=Type.GetTypeFromProgID("ADODB.Connection")!;dynamic con=Activator.CreateInstance(t)!;try{con.Provider=p;state="provider registered";}catch(Exception ex){state="not registered: "+ex.Message.Split('\n')[0];}finally{try{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(con);}catch{}}}catch(Exception ex){state="check failed: "+ex.Message;}x.Add("  "+p+": "+state);}
  x.Add("");x.Add("Unverified on a workstation: the scratch-database table and column names (LSETOFROMDISCOVER), the three LISP entry points, that WIREHDL1/2 and CMPHDL1/2 are entity handles of the wire segment and component at each end, that DWGIX counts from 1 in .wdp order, and every AutoCAD write. See README.");
  return string.Join(Environment.NewLine,x);}
}
